<?php $path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/'; ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TechSelectAI Account</title><style>body{font-family:Inter,Arial,sans-serif;background:#f7f9fc;color:#14213d;margin:0}.box{max-width:480px;margin:8vh auto;background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:28px}input,button,.oauth-btn{width:100%;box-sizing:border-box;padding:12px 14px;margin:8px 0;border-radius:10px;border:1px solid #cbd5e1}button{background:#2563eb;color:#fff;border:0;font-weight:700;cursor:pointer}.muted{color:#64748b}.msg{margin-top:12px;padding:10px;background:#f1f5f9;border-radius:10px;min-height:20px}a{color:#2563eb}.oauth{display:grid;gap:2px;margin:14px 0}.oauth-btn{display:none;text-align:center;text-decoration:none;background:#fff;color:#14213d;font-weight:700}.oauth-btn:hover{background:#f8fafc}.oauth-btn[data-ready="1"]{display:block}.divider{display:flex;align-items:center;gap:10px;color:#94a3b8;font-size:12px;margin:14px 0}.divider:before,.divider:after{content:"";height:1px;background:#e2e8f0;flex:1}.provider-note{font-size:12px;color:#64748b;margin:8px 0 0}</style></head><body><div class="box"><h1>TechSelectAI</h1><div id="app"></div></div><script>
const path=location.pathname,app=document.getElementById('app'),el=id=>document.getElementById(id);async function call(url,method='GET',body){const r=await fetch(url,{method,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw new Error(d.error||'Request failed');return d}function msg(t){const x=el('msg');if(x)x.textContent=t}function activeVisitorToken(){try{const x=JSON.parse(sessionStorage.getItem('techselectai.activeConsultation.v1')||'null');return x?.c?.visitor_token||''}catch{return''}}function safeNext(){const n=new URLSearchParams(location.search).get('next')||'';return n.startsWith('/')&&!n.startsWith('//')?n:'/my-consultations'}async function claimActive(csrf){const token=activeVisitorToken();if(!token)return 0;try{const r=await fetch('/api/account/claim-consultation',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({visitor_token:token})});const d=await r.json();return r.ok?Number(d.claimed||0):0}catch{return 0}}function oauthMarkup(){return `<div class="oauth"><a id="googleLogin" class="oauth-btn" href="#">Continue with Google</a><a id="microsoftLogin" class="oauth-btn" href="#">Continue with Microsoft</a><p class="provider-note">You can still use email and password.</p></div><div class="divider">or</div>`}async function setupOauth(){try{const p=await call('/api/auth/oauth/providers');const next=encodeURIComponent(safeNext());if(p.google){el('googleLogin').href='/api/auth/oauth/start?provider=google&next='+next;el('googleLogin').dataset.ready='1'}if(p.microsoft){el('microsoftLogin').href='/api/auth/oauth/start?provider=microsoft&next='+next;el('microsoftLogin').dataset.ready='1'}if(!p.google&&!p.microsoft){document.querySelector('.oauth')?.remove();document.querySelector('.divider')?.remove()}}catch{document.querySelector('.oauth')?.remove();document.querySelector('.divider')?.remove()}}async function finishOauth(){try{const d=await call('/api/auth/csrf');if(!d.user)throw new Error('signin_failed');localStorage.setItem('csrf',d.csrf_token);await claimActive(d.csrf_token);location.href=['admin','super_admin','reviewer','data_editor'].includes(d.user.role)?'/admin':safeNext()}catch{msg('External sign-in could not be completed. Please try again.')}}
if(path.includes('register')){app.innerHTML=`<h2>Create account</h2><p class="muted">Save and revisit your consultations.</p>${oauthMarkup()}<input id="fullName" placeholder="Name"><input id="email" type="email" placeholder="Email"><input id="pw" type="password" placeholder="Password (10+ characters)"><button id="go">Create account</button><div id="msg" class="msg"></div><p><a href="/login">Already have an account?</a></p>`;setupOauth();el('go').onclick=async()=>{try{let d=await call('/api/auth/register','POST',{name:el('fullName').value,email:el('email').value,password:el('pw').value});msg(d.verification_email_sent?'Check your email to verify your account.':'Account created, but email delivery needs hosting mail configuration.')}catch(e){msg(e.message)}}}
else if(path.includes('verify-email')){app.innerHTML=`<h2>Verify email</h2><button id="go">Verify now</button><div id="msg" class="msg"></div>`;el('go').onclick=async()=>{try{await call('/api/auth/verify','POST',{token:new URLSearchParams(location.search).get('token')});msg('Email verified. You can now sign in.')}catch(e){msg(e.message)}}}
else if(path.includes('reset-password')){app.innerHTML=`<h2>Reset password</h2><input id="pw" type="password" placeholder="New password (10+ characters)"><button id="go">Reset password</button><div id="msg" class="msg"></div>`;el('go').onclick=async()=>{try{await call('/api/auth/reset','POST',{token:new URLSearchParams(location.search).get('token'),password:el('pw').value});msg('Password updated.')}catch(e){msg(e.message)}}}
else{app.innerHTML=`<h2>Sign in</h2><p class="muted">Sign in to keep your software searches and consultations in one place.</p>${oauthMarkup()}<input id="email" type="email" placeholder="Email"><input id="pw" type="password" placeholder="Password"><button id="go">Sign in</button><div id="msg" class="msg"></div><p><a href="/register">Create account</a></p><p><button id="forgot" style="background:#fff;color:#2563eb;border:1px solid #cbd5e1">Send password reset</button></p>`;setupOauth();const q=new URLSearchParams(location.search);if(q.get('oauth')==='success'){msg('Sign-in successful. Finishing…');finishOauth()}else if(q.get('oauth_error'))msg(q.get('oauth_error')==='access_denied'?'Sign-in was cancelled.':'External sign-in failed. Please try again.');el('go').onclick=async()=>{try{let d=await call('/api/auth/login','POST',{email:el('email').value,password:el('pw').value});localStorage.setItem('csrf',d.csrf_token);await claimActive(d.csrf_token);location.href=['admin','super_admin','reviewer','data_editor'].includes(d.user.role)?'/admin':safeNext()}catch(e){msg(e.message)}};el('forgot').onclick=async()=>{try{await call('/api/auth/request-reset','POST',{email:el('email').value});msg('If the account exists, a reset email has been sent.')}catch(e){msg(e.message)}}}
</script></body></html>